// Emitted by FORGE from a recipe. Plain TypeScript: no network, no files, no eval.
type Json = null | boolean | number | string | Json[] | { [k: string]: Json };
type Row = Record<string, Json>;
function columns(rows: Row[], given?: string[]): string[] { const s = new Set<string>(given ?? []); for (const r of rows) for (const k of Object.keys(r)) s.add(k); return [...s]; }
export function run(tables: Record<string, Row[]>, cols: Record<string, string[]>, H: any): Record<string, Row[]> {
  {
  // step 1: summarize
  const T0 = tables["gmail_search"]; const T = T0;
  const groups = new Map<string, Row[]>();
  for (const r of T) { const k = H.key([H.own(r, "from")]); const list = groups.get(k); if (list) list.push(r); else groups.set(k, [r]); }
  const S0: Row[] = [];
  for (const g of groups.values()) { const o: Row = {};
    o["from"] = H.own(g[0], "from");
    o["count"] = g.length;
    S0.push(o); }
  tables["step1"] = S0;
  cols["step1"] = ["from","count"];
  }
  {
  // step 2: rename
  const T1 = tables["step1"]; const T = T1;
  const S1 = T.map((r) => { const o: Row = {}; for (const k of Object.keys(r)) o[({"from":"sender","count":"authorized_messages"} as Record<string, string>)[k] ?? k] = r[k]; return o; });
  tables["step2"] = S1;
  cols["step2"] = cols["step1"].map((c) => ({"from":"sender","count":"authorized_messages"} as Record<string, string>)[c] ?? c);
  }
  {
  // step 3: derive
  const T2 = tables["step2"]; const T = T2;
  const S2: Row[] = [];
  for (const r0 of T) { const r: Row = { ...r0 };
    r["sender_domain"] = H.call("lower", [() => H.call("split_part", [() => H.col(r, ["sender"]), () => "@", () => 1])]);
    S2.push(r); }
  tables["step3"] = S2;
  cols["step3"] = [...cols["step2"], ...["sender_domain"].filter((c, i, all) => !cols["step2"].includes(c) && all.indexOf(c) === i)];
  }
  {
  // step 4: summarize
  const T3 = tables["step3"]; const T = T3;
  const groups = new Map<string, Row[]>();
  for (const r of T) { const k = H.key([H.own(r, "sender_domain")]); const list = groups.get(k); if (list) list.push(r); else groups.set(k, [r]); }
  const S3: Row[] = [];
  for (const g of groups.values()) { const o: Row = {};
    o["sender_domain"] = H.own(g[0], "sender_domain");
    o["count"] = g.length;
    S3.push(o); }
  tables["step4"] = S3;
  cols["step4"] = ["sender_domain","count"];
  }
  {
  // step 5: rename
  const T4 = tables["step4"]; const T = T4;
  const S4 = T.map((r) => { const o: Row = {}; for (const k of Object.keys(r)) o[({"sender_domain":"domain","count":"authorized_messages_count"} as Record<string, string>)[k] ?? k] = r[k]; return o; });
  tables["step5"] = S4;
  cols["step5"] = cols["step4"].map((c) => ({"sender_domain":"domain","count":"authorized_messages_count"} as Record<string, string>)[c] ?? c);
  }
  {
  // step 6: derive
  const T5 = tables["step5"]; const T = T5;
  const S5: Row[] = [];
  for (const r0 of T) { const r: Row = { ...r0 };
    r["authorized_messages_count"] = H.call("round", [() => H.arith("/", H.col(r, ["authorized_messages_count"]), 1)]);
    S5.push(r); }
  tables["step6"] = S5;
  cols["step6"] = [...cols["step5"], ...["authorized_messages_count"].filter((c, i, all) => !cols["step5"].includes(c) && all.indexOf(c) === i)];
  }
  {
  // step 7: select
  const T6 = tables["step6"]; const T = T6;
  const S6 = T.map((r) => ({ "domain": H.own(r, "domain"), "authorized_messages_count": H.own(r, "authorized_messages_count") }));
  tables["step7"] = S6;
  cols["step7"] = ["domain","authorized_messages_count"];
  }
  {
  // step 8: sort
  const T7 = tables["step7"]; const T = T7;
  const dec = T.map((r, i) => ({ r, i, k: [H.col(r, ["domain"])] }));
  dec.sort((a, b) => { { const c = H.sortKey(a.k[0], b.k[0], false); if (c) return c; } return a.i - b.i; });
  const S7 = dec.map((d) => d.r);
  tables["step8"] = S7;
  cols["step8"] = cols["step7"];
  }
  tables.__final = tables["step8"];
  return tables;
}
